  '[{"id":"tc1","validation_type":"matching","expected_value":"Strengthens it","description_en":"Reasoning","description_id":"Penalaran","points":25},{"id":"tc2","validation_type":"matching","expected_value":"Weakens it","description_en":"Only image","description_id":"Hanya gambar","points":25},{"id":"tc3","validation_type":"matching","expected_value":"Strengthens it (depth)","description_en":"Depth","description_id":"Kedalaman","points":25},{"id":"tc4","validation_type":"matching","expected_value":"Weakens it (shallow)","description_en":"Shallow breadth","description_id":"Dangkal","points":25}]',
